function openBatchWorkForm(){
  const data=state(),parcels=active('parcelles',data),machines=active('materiels',data);if(!parcels.length)return toast('Aucune parcelle disponible.','error');
  modal('Travail groupé','Une seule saisie crée un travail relié pour chaque parcelle sélectionnée.',`<form id="batch-work-form"><div class="form-grid"><label class="span-2">Parcelles *</label><div class="span-2 batch-parcel-list">${parcels.map(p=>`<label class="check-row"><input type="checkbox" name="parcelIds" value="${p.id}"><span><strong>${escapeHtml(p.nom)}</strong><small>${escapeHtml(p.culture||'')} · ${formatNumber(p.surfaceHa)} ha</small></span></label>`).join('')}</div><div class="span-2"><button type="button" class="text-button" id="batch-select-all">Tout sélectionner</button> <button type="button" class="text-button" id="batch-clear">Effacer</button></div><label>Type *<input name="type" required placeholder="Fauche, semis…"></label><label>Date<input name="date" type="date" value="${todayIso()}" required></label><label>Statut<select name="status">${['À faire','En cours','Terminé'].map(v=>`<option>${v}</option>`).join('')}</select></label><label>Produit<input name="product"></label><label>Dose<input name="dose" inputmode="decimal"></label><label>Unité<select name="doseUnit"><option value="">—</option>${['kg/ha','L/ha','t/ha','m³/ha','unité/ha'].map(v=>`<option>${v}</option>`).join('')}</select></label><label>Matériel<select name="equipmentId"><option value="">Non renseigné</option>${machines.map(m=>`<option value="${m.id}">${escapeHtml(m.nom)}</option>`).join('')}</select></label><label>Coût total du lot (€)<input name="batchCost" inputmode="decimal" type="number" min="0" step=".01"></label><label class="span-2">Note<textarea name="note"></textarea></label></div></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="save-batch-work">Enregistrer le lot</button>`,'large');
  $('#batch-select-all').onclick=()=>$$('#batch-work-form input[name="parcelIds"]').forEach(x=>x.checked=true);$('#batch-clear').onclick=()=>$$('#batch-work-form input[name="parcelIds"]').forEach(x=>x.checked=false);
  $('#save-batch-work').onclick=async()=>{const form=$('#batch-work-form');if(!form.reportValidity())return;const ids=$$('#batch-work-form input[name="parcelIds"]:checked').map(x=>x.value);if(!ids.length)return toast('Sélectionnez au moins une parcelle.','error');const fd=new FormData(form),v=Object.fromEntries(fd),batchId=uid('batch'),selected=ids.map(id=>parcelById(id)).filter(Boolean),totalSurface=selected.reduce((sum,p)=>sum+toNumber(p.surfaceHa),0),batchCost=toNumber(v.batchCost);const entities=selected.map(p=>({batchId,parcelId:p.id,type:v.type,date:v.date,status:v.status,product:v.product,dose:toNullableNumber(v.dose)??v.dose,doseUnit:v.doseUnit,equipmentId:v.equipmentId,note:v.note,surfaceWorked:toNumber(p.surfaceHa),cost:batchCost&&totalSurface?batchCost*(toNumber(p.surfaceHa)/totalSurface):0,campaignId:campaignFor(v.date),source:'local'}));await store.upsertMany('interventions',entities,{label:`Travail groupé : ${v.type} · ${selected.length} parcelles`});closeModal();toast(`${selected.length} travaux créés dans le même lot.`);};
}

function routePointForParcel(parcel,data=state()){const entry=active('points',data).find(pt=>pt.parcelId===parcel.id&&normalize(pt.type).includes('entree')&&Number.isFinite(Number(pt.latitude))&&Number.isFinite(Number(pt.longitude)));return entry?{latitude:Number(entry.latitude),longitude:Number(entry.longitude),source:'Entrée de champ'}:{...geometryCentroid(parcel.geometry),source:'Centre de parcelle'};}
function orderedRouteStops(parcels,data=state()){
  let current=lastGps||(Number.isFinite(Number(data.exploitation.latitude))&&Number.isFinite(Number(data.exploitation.longitude))?{latitude:Number(data.exploitation.latitude),longitude:Number(data.exploitation.longitude)}:null);const remaining=parcels.map(parcel=>({parcel,point:routePointForParcel(parcel,data)})).filter(x=>Number.isFinite(Number(x.point?.latitude))&&Number.isFinite(Number(x.point?.longitude))),out=[];if(!current&&remaining.length)current=remaining[0].point;while(remaining.length){remaining.sort((a,b)=>haversineMeters(current,a.point)-haversineMeters(current,b.point));const next=remaining.shift();out.push(next);current=next.point;}return out;
}
function openDayRoute(){
  const data=state(),today=todayIso(),ids=[...new Set(active('interventions',data).filter(w=>workDate(w)===today&&!['Terminé','Annulé'].includes(w.status)).map(w=>w.parcelId))],parcels=ids.map(id=>parcelById(id,data)).filter(p=>p?.geometry),stops=orderedRouteStops(parcels,data);if(!stops.length)return modal('Tournée du jour','',`<div class="empty-state">Aucune parcelle géolocalisée avec un travail à faire aujourd’hui.</div>`,`<button class="button primary" data-action="close-modal">Fermer</button>`,'small');
  const total=stops.reduce((s,x)=>s+toNumber(x.parcel.surfaceHa),0);modal('Tournée du jour',`${stops.length} arrêt${stops.length>1?'s':''} · ${formatNumber(total)} ha`,`<ol class="route-list">${stops.map((s,i)=>`<li><span>${i+1}</span><div><strong>${escapeHtml(s.parcel.nom)}</strong><small>${escapeHtml(s.point.source)} · ${escapeHtml(s.parcel.culture||'')}</small></div><button class="small-button" data-action="route-parcel" data-id="${s.parcel.id}">Y aller</button></li>`).join('')}</ol>`,`<button class="button secondary" data-action="close-modal">Fermer</button><button class="button primary" id="start-day-route">Démarrer</button>`,'large');
  $('#start-day-route').onclick=()=>{const provider=state().preferences.routeProvider||'apple';if(provider==='google'&&stops.length>1){const dest=stops.at(-1).point,waypoints=stops.slice(0,-1).map(x=>`${x.point.latitude},${x.point.longitude}`).join('|');window.open(`https://www.google.com/maps/dir/?api=1&destination=${dest.latitude},${dest.longitude}&waypoints=${encodeURIComponent(waypoints)}`,'_blank','noopener');}else{const first=stops[0];routeParcel(first.parcel.id);} };
}

function openParcelActions(id){
  modal('Actions de la parcelle','Choisissez une action.',`<div class="stack-list"><button class="menu-row" data-action="edit-parcel" data-id="${id}"><span>✎</span><span><strong>Modifier</strong><small>Informations, économie et client</small></span><b>›</b></button><button class="menu-row" data-action="add-note" data-id="${id}"><span>☷</span><span><strong>Ajouter une note</strong><small>Note permanente de parcelle</small></span><b>›</b></button><button class="menu-row" data-action="add-photo" data-id="${id}"><span>▣</span><span><strong>Prendre une photo</strong><small>Caméra ou photothèque</small></span><b>›</b></button><button class="menu-row" data-action="draw-parcel" data-id="${id}"><span>◇</span><span><strong>Dessiner le contour</strong><small>Créer ou remplacer la géométrie</small></span><b>›</b></button><button class="menu-row" data-action="share-parcel" data-id="${id}"><span>↗</span><span><strong>Partager</strong><small>Résumé de parcelle</small></span><b>›</b></button><button class="menu-row" data-action="delete-parcel" data-id="${id}"><span>♲</span><span><strong>Placer dans la corbeille</strong><small>Récupérable ensuite</small></span><b>›</b></button></div>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`,'small');
}
function openNote(id){const p=parcelById(id);if(!p)return;modal('Note de parcelle',p.nom,`<label class="field-label">Note<textarea id="parcel-note" data-autofocus>${escapeHtml(p.notes||'')}</textarea></label>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="save-note">Enregistrer</button>`,'small');$('#save-note').onclick=async()=>{await store.upsert('parcelles',{...p,notes:$('#parcel-note').value},{label:`Note mise à jour : ${p.nom}`});closeModal();toast('Note enregistrée.');};}

function openAttachmentForm(parcelId,{photoOnly=false,interventionId=null}={}){
  modal(photoOnly?'Ajouter une photo':'Ajouter une pièce jointe','Le fichier reste local tant que la synchronisation cloud n’est pas activée.',`<form id="attachment-form"><label class="field-label">Fichier<input name="file" type="file" required ${photoOnly?'accept="image/*" capture="environment"':'accept="image/*,.pdf,.doc,.docx,.xls,.xlsx"'}></label><label class="field-label" style="margin-top:12px">Commentaire<input name="note" maxlength="240"></label></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="save-attachment">Enregistrer</button>`,'small');
  $('#save-attachment').onclick=async()=>{const form=$('#attachment-form'),file=form.file.files[0];if(!file)return;const type=file.type.startsWith('image/')?'photos':'documents',id=uid(type==='photos'?'photo':'doc');await store.storage.blobPut(id,file);await store.upsert(type,{id,parcelId,interventionId:interventionId||null,name:file.name,mimeType:file.type,size:file.size,note:form.note.value,kind:type==='photos'?'photo':'document',source:'local'},{label:`Pièce jointe ajoutée : ${file.name}`,queue:false});closeModal();toast('Fichier enregistré.');};
}
async function viewAttachment(type,id){const item=store.get(type,id),blob=await store.storage.blobGet(id);if(!item||!blob){toast('Fichier introuvable dans le stockage local.','error');return;}const url=URL.createObjectURL(blob);if(type==='photos'){modal(item.name||'Photo',item.note||'',`<img src="${url}" alt="${escapeHtml(item.note||item.name||'Photo')}" style="display:block;max-width:100%;max-height:65dvh;margin:auto;border-radius:14px">`,`<button class="button secondary" data-action="close-modal">Fermer</button><button class="button secondary" id="download-attachment">Télécharger</button><button class="button danger" id="delete-attachment">Supprimer</button>`,'large');}else{modal(item.name||'Document',item.note||'',`<div class="empty-state">${escapeHtml(item.mimeType||'Document')} · ${formatNumber((item.size||0)/1024)} Ko</div>`,`<button class="button secondary" data-action="close-modal">Fermer</button><button class="button primary" id="download-attachment">Télécharger</button><button class="button danger" id="delete-attachment">Supprimer</button>`,'small');}$('#download-attachment').onclick=()=>downloadBlob(item.name||`${id}.bin`,blob);$('#delete-attachment').onclick=()=>confirmDelete(type,id,'ce fichier');setTimeout(()=>URL.revokeObjectURL(url),60000);}

function confirmDelete(type,id,label='cet élément'){
  modal('Placer dans la corbeille','Cette action est réversible depuis Mes données.',`<div class="notice warning">Retirer ${escapeHtml(label)} ?</div>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="confirm-delete">Placer dans la corbeille</button>`,'small');
  $('#confirm-delete').onclick=async()=>{await store.remove(type,id);closeModal();toast('Élément placé dans la corbeille.','success',{label:'Annuler',run:()=>store.restore(type,id)});};
}

function openMapLayers(){const prefs=state().preferences;modal('Couches de la carte','Choisissez ce que la carte doit montrer.',`<form id="map-layer-form"><div class="form-grid"><label>Couleur des parcelles<select name="mapColorMode"><option value="culture" ${prefs.mapColorMode==='culture'?'selected':''}>Par culture</option><option value="status" ${prefs.mapColorMode==='status'?'selected':''}>Par statut</option></select></label><label>Fond de carte<select name="mapLayer"><option value="osm" ${prefs.mapLayer==='osm'?'selected':''}>Standard</option><option value="satellite" ${prefs.mapLayer==='satellite'?'selected':''}>Satellite</option></select></label><label><input type="checkbox" name="rpg" ${parcelMap.rpgVisible?'checked':''}> Parcelles PAC/RPG alentours</label><label>Rayon RPG<select name="radius"><option value="5">5 km</option><option value="10">10 km</option></select></label></div></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="apply-map-layers">Appliquer</button>`,'small');
  $('#apply-map-layers').onclick=async()=>{const form=$('#map-layer-form'),v=Object.fromEntries(new FormData(form));await store.setPreferences({mapColorMode:v.mapColorMode,mapLayer:v.mapLayer});parcelMap.setColorMode(v.mapColorMode);parcelMap.setBaseLayer(v.mapLayer);if(form.rpg.checked){try{const ref=lastGps||geometryCentroid(parcelById(selectedParcelId)?.geometry)||{latitude:state().exploitation.latitude,longitude:state().exploitation.longitude};if(!Number.isFinite(Number(ref?.latitude))||!Number.isFinite(Number(ref?.longitude)))throw new Error('Localisez-vous ou renseignez les coordonnées de l’exploitation.');const count=await parcelMap.loadRpgNearby({latitude:Number(ref.latitude),longitude:Number(ref.longitude),radiusKm:Number(v.radius),year:2024});toast(`${count} parcelle${count!==1?'s':''} RPG chargée${count!==1?'s':''}.`);}catch(error){toast(error.message,'error');}}else parcelMap.setRpgVisible(false);closeModal();};
}

function openPointCreator(){
  modal('Ajouter un point','Choisissez le type puis touchez son emplacement sur la carte.',`<form id="point-form" class="form-grid"><label>Type<select name="type"><option>À faire</option><option>Entrée de champ</option><option>Zone humide</option><option>Point d’eau</option><option>Arbre</option><option>Regard / équipement</option><option>Autre</option></select></label><label>Nom<input name="nom" placeholder="Nom facultatif"></label><label class="span-2">Note<textarea name="note"></textarea></label></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="place-point">Choisir sur la carte</button>`,'small');
  $('#place-point').onclick=()=>{const v=Object.fromEntries(new FormData($('#point-form')));closeModal();toast('Touchez la carte à l’emplacement du point.');parcelMap.startPointPlacement(async coords=>{const nearest=nearestParcel(coords,state());await store.upsert('points',{...v,...coords,parcelId:nearest?.distance<100?nearest.parcel.id:null,source:'local'},{label:`Point ajouté : ${v.nom||v.type}`});toast('Point enregistré.');});};
}

function nearestParcel(position,data=state()){
  const rows=active('parcelles',data).filter(p=>p.geometry).map(parcel=>{const inside=pointInGeometry(position.longitude,position.latitude,parcel.geometry);const center=geometryCentroid(parcel.geometry);return{parcel,distance:inside?0:haversineMeters(position,center),inside};}).sort((a,b)=>a.distance-b.distance);return rows[0]||null;
}

async function requestGps(){
  if(state().preferences.gpsConsent){parcelMap.locate();return;}
  modal('Utiliser votre position ?','Le GPS est demandé uniquement quand vous utilisez une fonction de localisation.',`<div class="notice info">La position sert à vous placer sur la carte, trouver les parcelles proches et préparer les itinéraires. Elle reste sur cet appareil sauf si vous déclenchez explicitement une fonction de partage ou de synchronisation.</div>`,`<button class="button secondary" data-action="close-modal">Pas maintenant</button><button class="button primary" id="allow-gps">Continuer</button>`,'small');
  $('#allow-gps').onclick=async()=>{await store.setPreferences({gpsConsent:true});closeModal();parcelMap.locate();};
}

function closeFieldMode(){const overlay=$('#field-mode');if(overlay)overlay.remove();fieldModeOpen=false;}

function openFieldMode(){
  if(fieldModeOpen)return;fieldModeOpen=true;const overlay=document.createElement('section');overlay.id='field-mode';overlay.className='field-mode-overlay';overlay.innerHTML=`<div class="field-mode-card"><div class="view-heading"><div><p class="eyebrow">Mode terrain</p><h1>Sur le terrain</h1></div><button class="icon-button" id="close-field" aria-label="Fermer">×</button></div><div id="field-gps" class="panel"><strong>Position non demandée</strong><p class="form-note">Le GPS n’est utilisé qu’après votre action.</p><button class="button primary" id="field-locate">◎ Me localiser</button></div><div id="field-current"></div><div class="field-quick-actions"><button data-action="new-work">＋<small>Travail</small></button><button id="field-photo">▣<small>Photo</small></button><button id="field-note">☷<small>Note</small></button><button id="field-point">⌖<small>Point</small></button></div><article class="panel"><div class="panel-heading"><h2>Parcelles proches</h2></div><div id="field-nearby" class="stack-list"><div class="empty-state">Localisez-vous pour calculer les distances.</div></div></article></div>`;document.body.append(overlay);$('#close-field').onclick=closeFieldMode;$('#field-locate').onclick=()=>requestGps();$('#field-photo').onclick=()=>{const id=nearestParcel(lastGps||{},state())?.parcel?.id;if(!id)return toast('Aucune parcelle proche détectée.','error');closeFieldMode();openAttachmentForm(id,{photoOnly:true});};$('#field-note').onclick=()=>{const id=nearestParcel(lastGps||{},state())?.parcel?.id;if(!id)return toast('Aucune parcelle proche détectée.','error');closeFieldMode();openNote(id);};$('#field-point').onclick=()=>{closeFieldMode();switchView('map');openPointCreator();};if(lastGps)renderFieldGps(lastGps);else requestGps();
}
function renderFieldGps(detail){
  const root=$('#field-gps');if(!root)return;root.innerHTML=`<strong>${escapeHtml(detail.status||'Position')}</strong><p class="form-note">Précision ± ${Math.round(detail.accuracy)} m · position conservée localement</p><button class="button secondary" id="field-relocate">Actualiser</button>`;$('#field-relocate').onclick=()=>requestGps();const rows=active('parcelles').filter(p=>p.geometry).map(p=>{const inside=pointInGeometry(detail.longitude,detail.latitude,p.geometry);return{parcel:p,inside,distance:inside?0:haversineMeters(detail,geometryCentroid(p.geometry))};}).sort((a,b)=>a.distance-b.distance);const current=rows.find(r=>r.inside);$('#field-current').innerHTML=current?`<article class="panel" style="margin:12px 0"><p class="eyebrow">Vous êtes dans</p><h2>${escapeHtml(current.parcel.nom)}</h2><p>${escapeHtml(current.parcel.culture||'Culture non renseignée')} · ${formatNumber(current.parcel.surfaceHa)} ha</p><button class="button primary" data-action="open-parcel" data-id="${current.parcel.id}">Ouvrir</button></article>`:'';$('#field-nearby').innerHTML=rows.slice(0,5).map(r=>`<div class="list-row"><div><strong>${escapeHtml(r.parcel.nom)}</strong><small>${r.inside?'Vous êtes ici':r.distance<1000?`${Math.round(r.distance)} m`:`${(r.distance/1000).toFixed(1)} km`} · ${escapeHtml(r.parcel.culture||'')}</small></div><button class="small-button" data-action="open-parcel" data-id="${r.parcel.id}">Ouvrir</button></div>`).join('')||'<div class="empty-state">Aucune parcelle géolocalisée.</div>';
}

function openRotations(){
  const data=state(),parcels=active('parcelles',data),rotations=active('rotations',data);const cultureArea=parcels.reduce((acc,p)=>{const c=p.culture||'Sans culture';acc[c]=(acc[c]||0)+toNumber(p.surfaceHa);return acc;},{});const entries=Object.entries(cultureArea).sort((a,b)=>b[1]-a[1]),total=entries.reduce((s,e)=>s+e[1],0);
  modal('Assolement',`${parcels.length} parcelles · ${formatNumber(total)} ha`,`<div class="culture-bars">${entries.map(([culture,area])=>`<div class="culture-bar-row"><strong>${escapeHtml(culture)}</strong><div class="culture-bar-track"><div class="culture-bar-fill" style="width:${total?area/total*100:0}%"></div></div><span>${formatNumber(area)} ha</span></div>`).join('')}</div><h3>Rotations</h3><div class="table-wrap"><table><thead><tr><th>Parcelle</th><th>Culture</th><th>Historique</th><th></th></tr></thead><tbody>${parcels.map(p=>{const hist=rotations.filter(r=>r.parcelId===p.id).sort((a,b)=>String(b.campaignId).localeCompare(String(a.campaignId)));return`<tr><td>${escapeHtml(p.nom)}</td><td>${escapeHtml(p.culture||'—')}</td><td>${hist.map(r=>`<button class="rotation-chip" data-action="edit-rotation" data-id="${r.id}" title="Modifier ${escapeHtml(r.campaignId)}">${escapeHtml(r.campaignId)} · ${escapeHtml(r.culture)}</button>`).join(' ')||'—'}</td><td><button class="text-button" data-action="add-rotation" data-id="${p.id}">Ajouter</button></td></tr>`;}).join('')}</tbody></table></div>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`,'large');
}
function openRotationForm(parcelId,rotation=null){const p=parcelById(parcelId);if(!p)return;const r=rotation||{campaignId:campaignFor(),culture:p.culture||''};modal(rotation?'Modifier la rotation':'Ajouter une rotation',p.nom,`<form id="rotation-form" class="form-grid"><label>Campagne<input name="campaignId" required value="${escapeHtml(r.campaignId||campaignFor())}"></label><label>Culture<input name="culture" required value="${escapeHtml(r.culture||'')}"></label></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button>${rotation?'<button class="button danger" id="delete-rotation">Supprimer</button>':''}<button class="button primary" id="save-rotation">Enregistrer</button>`,'small');$('#save-rotation').onclick=async()=>{const f=$('#rotation-form');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));await store.upsert('rotations',{...(rotation||{}),parcelId,...v},{label:`Rotation ${rotation?'modifiée':'ajoutée'} : ${p.nom}`});closeModal();openRotations();toast('Rotation enregistrée.');};$('#delete-rotation')?.addEventListener('click',()=>confirmDelete('rotations',rotation.id,'cette rotation'));}

function openEquipment(){const machines=active('materiels');modal('Matériel','Suivez les compteurs et les échéances.',`<div class="stack-list">${machines.length?machines.map(m=>{const remaining=toNullableNumber(m.maintenanceDue)!==null&&toNullableNumber(m.currentMeter)!==null?toNumber(m.maintenanceDue)-toNumber(m.currentMeter):null;return`<div class="list-row"><div><strong>${escapeHtml(m.nom)}</strong><small>${formatNumber(m.currentMeter)} h${remaining!==null?` · ${remaining<=0?'entretien dépassé':`entretien dans ${formatNumber(remaining)} h`}`:''}</small></div><button class="small-button" data-action="edit-equipment" data-id="${m.id}">Modifier</button></div>`;}).join(''):'<div class="empty-state">Aucun matériel.</div>'}</div>`,`<button class="button secondary" data-action="close-modal">Fermer</button><button class="button primary" data-action="new-equipment">＋ Matériel</button>`);}
function openEquipmentForm(machine=null){const m=machine||{nom:'',currentMeter:'',maintenanceDue:'',hourlyCost:'',actualFuel:'',insurance:'',amortization:''};modal(machine?'Modifier le matériel':'Nouveau matériel','',`<form id="equipment-form" class="form-grid"><label>Nom *<input name="nom" required value="${escapeHtml(m.nom)}"></label><label>Compteur actuel (h)<input name="currentMeter" type="number" min="0" step=".1" value="${m.currentMeter??''}"></label><label>Entretien prévu à (h)<input name="maintenanceDue" type="number" min="0" step=".1" value="${m.maintenanceDue??''}"></label><label>Coût horaire (€)<input name="hourlyCost" type="number" min="0" step=".01" value="${m.hourlyCost??''}"></label><label>Consommation (L/h)<input name="actualFuel" type="number" min="0" step=".1" value="${m.actualFuel??''}"></label><label>Assurance annuelle (€)<input name="insurance" type="number" min="0" step=".01" value="${m.insurance??''}"></label><label>Amortissement annuel (€)<input name="amortization" type="number" min="0" step=".01" value="${m.amortization??''}"></label></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button>${machine?'<button class="button secondary" id="delete-equipment">Supprimer</button>':''}<button class="button primary" id="save-equipment">Enregistrer</button>`);$('#save-equipment').onclick=async()=>{const f=$('#equipment-form');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));for(const k of ['currentMeter','maintenanceDue','hourlyCost','actualFuel','insurance','amortization'])v[k]=toNullableNumber(v[k]);await store.upsert('materiels',{...m,...v},{label:`Matériel ${machine?'modifié':'créé'} : ${v.nom}`});closeModal();toast('Matériel enregistré.');};$('#delete-equipment')?.addEventListener('click',()=>confirmDelete('materiels',m.id,'ce matériel'));}

function grazingTotal(session){return Array.isArray(session.animals)&&session.animals.length?session.animals.length+toNumber(session.additionalAnimalsCount):toNumber(session.animalsCount);}
function openGrazing(){const data=state(),sessions=active('grazingSessions',data).filter(s=>!s.endDate),parcels=new Map(active('parcelles',data).map(p=>[p.id,p]));modal('Pâturage','Animaux actuellement au pré.',`<div class="stack-list">${sessions.length?sessions.map(s=>`<div class="list-row"><div><strong>${escapeHtml(parcels.get(s.parcelId)?.nom||'Parcelle')}</strong><small>${grazingTotal(s)} animaux · depuis le ${localDate(s.startDate)}${s.animals?.some(a=>a.gestation)?` · ${s.animals.filter(a=>a.gestation).length} gestante(s)`:''}</small></div><div><button class="small-button" data-action="edit-grazing" data-id="${s.id}">Modifier</button> <button class="small-button" data-action="end-grazing" data-id="${s.id}">Sortir</button></div></div>`).join(''):'<div class="empty-state">Aucun lot actuellement au pré.</div>'}</div>`,`<button class="button secondary" data-action="close-modal">Fermer</button><button class="button primary" data-action="new-grazing">Mettre au pré</button>`);}
function openGrazingForm(session=null){const parcels=active('parcelles'),g=session||{parcelId:parcels[0]?.id||'',startDate:todayIso(),animals:[],additionalAnimalsCount:0,note:''};const animalText=(g.animals||[]).map(a=>`${a.number||''}${a.gestation?' | gestante':''}`).join('\n');modal(session?'Modifier le pâturage':'Mettre au pré','Une ligne par animal. Ajoutez « | gestante » après le numéro si nécessaire.',`<form id="grazing-form" class="form-grid"><label>Parcelle<select name="parcelId">${parcels.map(p=>`<option value="${p.id}" ${g.parcelId===p.id?'selected':''}>${escapeHtml(p.nom)}</option>`).join('')}</select></label><label>Date<input name="startDate" type="date" value="${escapeHtml(g.startDate||todayIso())}"></label><label class="span-2">Numéros des animaux<textarea name="animals" rows="7" placeholder="FR1234567890\nFR1234567891 | gestante">${escapeHtml(animalText)}</textarea></label><label>Animaux sans numéro<input name="additionalAnimalsCount" type="number" min="0" step="1" value="${toNumber(g.additionalAnimalsCount)}"></label><label>Lot / commentaire<input name="note" value="${escapeHtml(g.note||'')}"></label></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button>${session?'<button class="button danger" id="delete-grazing">Supprimer</button>':''}<button class="button primary" id="save-grazing">Enregistrer</button>`,'large');$('#save-grazing').onclick=async()=>{const f=$('#grazing-form'),v=Object.fromEntries(new FormData(f));const animals=String(v.animals||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>{const [number,...flags]=line.split('|').map(x=>x.trim());return{number,gestation:normalize(flags.join(' ')).includes('gestant')};});const additionalAnimalsCount=Math.max(0,Math.floor(toNumber(v.additionalAnimalsCount)));await store.upsert('grazingSessions',{...g,parcelId:v.parcelId,startDate:v.startDate,animals,additionalAnimalsCount,animalsCount:animals.length+additionalAnimalsCount,note:v.note,endDate:g.endDate||null},{label:`Pâturage ${session?'modifié':'enregistré'}.`});closeModal();openGrazing();toast('Pâturage enregistré.');};$('#delete-grazing')?.addEventListener('click',()=>confirmDelete('grazingSessions',g.id,'cette session de pâturage'));}

function openClients(){const clients=active('clients'),parcels=active('parcelles');modal('Clients','Parcelles et prestations.',`<div class="stack-list">${clients.length?clients.map(c=>{const ps=parcels.filter(p=>p.clientId===c.id);return`<div class="list-row"><div><strong>${escapeHtml(c.name)}</strong><small>${ps.length} parcelle${ps.length!==1?'s':''} · ${formatNumber(ps.reduce((s,p)=>s+toNumber(p.surfaceHa),0))} ha</small></div><button class="small-button" data-action="edit-client" data-id="${c.id}">Modifier</button></div>`;}).join(''):'<div class="empty-state">Aucun client enregistré.</div>'}</div>`,`<button class="button secondary" data-action="close-modal">Fermer</button><button class="button primary" data-action="new-client">＋ Client</button>`);}
function openClientForm(client=null){const c=client||{name:'',contact:'',note:''};modal(client?'Modifier le client':'Nouveau client','',`<form id="client-form" class="form-grid"><label>Nom *<input name="name" required value="${escapeHtml(c.name)}"></label><label>Contact<input name="contact" value="${escapeHtml(c.contact||'')}"></label><label class="span-2">Note<textarea name="note">${escapeHtml(c.note||'')}</textarea></label></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="save-client">Enregistrer</button>`,'small');$('#save-client').onclick=async()=>{const f=$('#client-form');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));await store.upsert('clients',{...c,...v},{label:`Client ${client?'modifié':'créé'} : ${v.name}`});closeModal();toast('Client enregistré.');};}

function openTasks(){
  const data=state(),parcels=new Map(active('parcelles',data).map(p=>[p.id,p.nom]));const tasks=active('tasks',data).sort((a,b)=>String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999')));
  modal('Tâches','Petites actions et échéances indépendantes des travaux agricoles.',`${tasks.length?`<div class="stack-list">${tasks.map(t=>`<div class="list-row"><div><strong>${escapeHtml(t.title||'Tâche')}</strong><small>${t.parcelId?`${escapeHtml(parcels.get(t.parcelId)||'Parcelle')} · `:''}${t.dueDate?localDate(t.dueDate):'Sans échéance'} · ${escapeHtml(t.status||'À faire')}</small></div><div><button class="small-button" data-action="edit-task" data-id="${t.id}">Modifier</button>${t.status!=='Terminé'?` <button class="small-button" data-action="finish-task" data-id="${t.id}">Terminer</button>`:''}</div></div>`).join('')}</div>`:'<div class="empty-state">Aucune tâche.</div>'}`,`<button class="button secondary" data-action="close-modal">Fermer</button><button class="button primary" data-action="new-task">＋ Tâche</button>`,'large');
}
function openTaskForm(task=null){
  const data=state(),parcels=active('parcelles',data),t=task||{title:'',dueDate:todayIso(),parcelId:'',status:'À faire',priority:'Normale',note:''};
  modal(task?'Modifier la tâche':'Nouvelle tâche','Une tâche sert aux rappels simples ; un travail reste dans le journal agricole.',`<form id="task-form" class="form-grid"><label class="span-2">Tâche *<input name="title" required data-autofocus value="${escapeHtml(t.title||'')}"></label><label>Échéance<input name="dueDate" type="date" value="${escapeHtml(t.dueDate||'')}"></label><label>Statut<select name="status">${['À faire','En cours','Terminé'].map(v=>`<option ${t.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Parcelle<select name="parcelId"><option value="">Aucune</option>${parcels.map(p=>`<option value="${p.id}" ${t.parcelId===p.id?'selected':''}>${escapeHtml(p.nom)}</option>`).join('')}</select></label><label>Priorité<select name="priority">${['Basse','Normale','Haute'].map(v=>`<option ${t.priority===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="span-2">Note<textarea name="note">${escapeHtml(t.note||'')}</textarea></label></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button>${task?'<button class="button danger" id="delete-task">Supprimer</button>':''}<button class="button primary" id="save-task">Enregistrer</button>`,'small');
  $('#save-task').onclick=async()=>{const form=$('#task-form');if(!form.reportValidity())return;const v=Object.fromEntries(new FormData(form));await store.upsert('tasks',{...t,...v},{label:`Tâche ${task?'modifiée':'créée'} : ${v.title}`});closeModal();toast('Tâche enregistrée.');};$('#delete-task')?.addEventListener('click',()=>confirmDelete('tasks',t.id,'cette tâche'));
}
function openCalendar(baseDate=new Date()){
  const d=new Date(baseDate);const year=d.getFullYear(),month=d.getMonth(),first=new Date(year,month,1),last=new Date(year,month+1,0),offset=(first.getDay()+6)%7;const data=state(),parcels=new Map(active('parcelles',data).map(p=>[p.id,p.nom]));const works=active('interventions',data),tasks=active('tasks',data);const key=date=>isoDate(date);const events=new Map();
  const add=(date,item)=>{if(!date)return;const arr=events.get(date)||[];arr.push(item);events.set(date,arr);};works.forEach(w=>add(workDate(w),{kind:'work',label:w.type,parcel:parcels.get(w.parcelId),id:w.id,status:w.status}));tasks.forEach(t=>add(t.dueDate,{kind:'task',label:t.title,parcel:parcels.get(t.parcelId),id:t.id,status:t.status}));
  const cells=[];for(let i=0;i<offset;i++)cells.push('<div class="calendar-day is-empty"></div>');for(let day=1;day<=last.getDate();day++){const date=key(new Date(year,month,day)),items=events.get(date)||[],isToday=date===todayIso();cells.push(`<button class="calendar-day ${isToday?'is-today':''}" data-action="calendar-day" data-date="${date}"><span>${day}</span>${items.slice(0,3).map(e=>`<small class="calendar-dot ${e.kind}">${escapeHtml(e.label)}</small>`).join('')}${items.length>3?`<small>+${items.length-3}</small>`:''}</button>`);}const monthLabel=new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric'}).format(first);
  modal('Calendrier',monthLabel,`<div class="calendar-toolbar"><button class="small-button" id="calendar-prev">‹</button><strong>${escapeHtml(monthLabel)}</strong><button class="small-button" id="calendar-next">›</button></div><div class="calendar-weekdays">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells.join('')}</div><div id="calendar-day-detail" style="margin-top:16px"><div class="empty-state">Touchez un jour pour afficher son planning.</div></div>`,`<button class="button secondary" data-action="open-tasks">Tâches</button><button class="button primary" data-action="new-work">＋ Travail</button>`,'large');
  $('#calendar-prev').onclick=()=>openCalendar(new Date(year,month-1,1));$('#calendar-next').onclick=()=>openCalendar(new Date(year,month+1,1));
}
function renderCalendarDay(date){const root=$('#calendar-day-detail');if(!root)return;const data=state(),parcels=new Map(active('parcelles',data).map(p=>[p.id,p.nom]));const works=active('interventions',data).filter(w=>workDate(w)===date),tasks=active('tasks',data).filter(t=>t.dueDate===date);root.innerHTML=`<h3>${localDate(date)}</h3>${works.map(w=>`<div class="list-row"><div><strong>${escapeHtml(w.type)}</strong><small>${escapeHtml(parcels.get(w.parcelId)||'Parcelle')} · ${escapeHtml(w.status||'')}</small></div><button class="small-button" data-action="edit-work" data-id="${w.id}">Ouvrir</button></div>`).join('')}${tasks.map(t=>`<div class="list-row"><div><strong>${escapeHtml(t.title)}</strong><small>Tâche · ${escapeHtml(t.status||'')}</small></div><button class="small-button" data-action="edit-task" data-id="${t.id}">Ouvrir</button></div>`).join('')||(!works.length?'<div class="empty-state">Rien de prévu ce jour.</div>':'')}`;}

function openWeather(){if(!weatherCache){refreshWeather().then(()=>{if(weatherCache)openWeather();});return;}const w=weatherCache;const start=Math.max(0,w.hourly.time.findIndex(t=>new Date(t)>=new Date()) );modal('Météo',`Prévisions basées sur ${w.place}.`,`<div class="weather-main"><div class="weather-temp">${Math.round(w.current.temperature_2m)}°</div><div><strong>${escapeHtml(w.place)}</strong><br><small>Vent ${Math.round(w.current.wind_speed_10m)} km/h · rafales ${Math.round(w.current.wind_gusts_10m||0)} km/h</small></div></div><h3>Prochaines heures</h3><div class="table-wrap"><table><thead><tr><th>Heure</th><th>Temp.</th><th>Pluie</th><th>Vent</th><th>Rafales</th></tr></thead><tbody>${w.hourly.time.slice(start,start+12).map((t,i)=>{const idx=start+i;return`<tr><td>${new Date(t).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</td><td>${Math.round(w.hourly.temperature_2m[idx])}°</td><td>${Math.round(w.hourly.precipitation_probability[idx]||0)} %</td><td>${Math.round(w.hourly.wind_speed_10m[idx]||0)} km/h</td><td>${Math.round(w.hourly.wind_gusts_10m[idx]||0)} km/h</td></tr>`;}).join('')}</tbody></table></div><h3>${w.daily.time.length} jours</h3><div class="table-wrap"><table><thead><tr><th>Jour</th><th>Min / max</th><th>Pluie</th><th>Vent max</th></tr></thead><tbody>${w.daily.time.map((d,i)=>`<tr><td>${localDate(d)}</td><td>${Math.round(w.daily.temperature_2m_min[i])}° / ${Math.round(w.daily.temperature_2m_max[i])}°</td><td>${Math.round(w.daily.precipitation_probability_max[i]||0)} % · ${formatNumber(w.daily.precipitation_sum[i]||0)} mm</td><td>${Math.round(w.daily.wind_speed_10m_max[i]||0)} km/h</td></tr>`).join('')}</tbody></table></div>`,`<button class="button secondary" data-action="refresh-weather">Actualiser</button><button class="button primary" data-action="close-modal">Fermer</button>`,'large');}

function openAssistant(){modal('Assistant','Posez une question sur les données présentes sur cet appareil.',`<div id="assistant-thread" class="stack-list"><div class="notice info">Exemples : « surface en maïs », « parcelles sans culture », « travaux aujourd’hui », « combien de parcelles ? »</div></div><form id="assistant-form" style="display:flex;gap:8px;margin-top:14px"><input id="assistant-input" data-autofocus placeholder="Votre question…" style="flex:1;min-height:46px;border:1px solid var(--border);border-radius:12px;padding:0 12px;font-size:16px"><button class="button primary">Envoyer</button></form>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`,'large');$('#assistant-form').onsubmit=e=>{e.preventDefault();const q=$('#assistant-input').value.trim();if(!q)return;assistantAnswer(q);$('#assistant-input').value='';};}
function assistantAnswer(question){const data=state(),q=normalize(question),parcels=active('parcelles',data),works=active('interventions',data),thread=$('#assistant-thread');let answer='Je n’ai pas reconnu la demande. Essayez un nom de parcelle, une culture, « travaux aujourd’hui » ou « sans culture ».';
  const matchedParcel=[...parcels].sort((a,b)=>b.nom.length-a.nom.length).find(p=>q.includes(normalize(p.nom)));
  const createIntent=/\b(ajoute|ajouter|cree|creer|planifie|planifier|enregistre|enregistrer)\b/.test(q);
  if(createIntent&&matchedParcel){const verbs=['ajoute','ajouter','cree','creer','planifie','planifier','enregistre','enregistrer'];let type=question;const lower=normalize(question);for(const verb of verbs){const idx=lower.indexOf(verb);if(idx>=0){type=question.slice(idx+verb.length);break;}}type=type.replace(new RegExp(`\\s+(sur|dans)\\s+${matchedParcel.nom.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}.*$`,'i'),'').replace(/\b(aujourd’hui|aujourd'hui|demain)\b/ig,'').trim().replace(/^un[e]?\s+/i,'');if(!type)type='Travail';const tomorrow=/\bdemain\b/.test(q),date=tomorrow?isoDate(Date.now()+86400000):todayIso(),status=/\b(planifie|planifier)\b/.test(q)||tomorrow?'À faire':'Terminé';assistantConfirmWork({parcel:matchedParcel,type,date,status});return;}
  if(q.includes('sans culture')){const list=parcels.filter(p=>!p.culture);answer=`${list.length} parcelle${list.length!==1?'s':''} sans culture${list.length?` : ${list.slice(0,8).map(p=>p.nom).join(', ')}`:''}.`;}
  else if(q.includes('travaux aujourd')){const list=works.filter(w=>workDate(w)===todayIso());answer=`${list.length} travail${list.length!==1?'aux':''} aujourd’hui${list.length?` : ${list.slice(0,8).map(w=>`${w.type} — ${parcelById(w.parcelId,data)?.nom||'parcelle'}`).join(' ; ')}`:''}.`;}
  else if(q.includes('combien')&&q.includes('parcelle'))answer=`${parcels.length} parcelles actives, pour ${formatNumber(parcels.filter(p=>p.ownershipType==='own').reduce((sum,p)=>sum+toNumber(p.surfaceHa),0))} ha de l’exploitation.`;
  else {const culture=parcels.find(p=>p.culture&&q.includes(normalize(p.culture)))?.culture;if(culture&&q.includes('surface')){const list=parcels.filter(p=>normalize(p.culture)===normalize(culture));answer=`${formatNumber(list.reduce((sum,p)=>sum+toNumber(p.surfaceHa),0))} ha en ${culture}, répartis sur ${list.length} parcelle${list.length!==1?'s':''}.`;}else if(matchedParcel){const p=matchedParcel,last=works.filter(w=>w.parcelId===p.id).sort((a,b)=>String(workDate(b)).localeCompare(String(workDate(a))))[0];answer=`${p.nom} : ${formatNumber(p.surfaceHa)} ha, ${p.culture||'culture non renseignée'}${p.commune?`, ${p.commune}`:''}.${last?` Dernier travail : ${last.type} le ${localDate(workDate(last))}.`:''}`;}}
  const item=document.createElement('div');item.className='assistant-answer';item.innerHTML=`<strong>Vous</strong><p>${escapeHtml(question)}</p><strong>Assistant</strong><p>${escapeHtml(answer)}</p>`;thread.append(item);thread.scrollTop=thread.scrollHeight;
}
function assistantConfirmWork({parcel,type,date,status}){modal('Confirmer l’action','L’assistant ne modifie jamais vos données sans confirmation.',`<div class="preview-summary"><div class="preview-stat"><strong>${escapeHtml(type)}</strong><small>travail</small></div><div class="preview-stat"><strong>${escapeHtml(parcel.nom)}</strong><small>parcelle</small></div><div class="preview-stat"><strong>${escapeHtml(localDate(date))}</strong><small>date</small></div></div><div class="notice info">Statut : ${escapeHtml(status)}</div>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="assistant-confirm-work">Confirmer</button>`,'small');$('#assistant-confirm-work').onclick=async()=>{await store.upsert('interventions',{parcelId:parcel.id,type,date,status,surfaceWorked:toNumber(parcel.surfaceHa),cost:0,campaignId:campaignFor(date),source:'assistant-local'},{label:`Travail créé avec confirmation : ${type}`});closeModal();toast('Travail créé.','success');};}

function openReports(){modal('Rapports & exports','Exportez uniquement ce dont vous avez besoin.',`<div class="stack-list"><button class="menu-row" data-action="export-work-csv"><span>CSV</span><span><strong>Travaux</strong><small>Historique complet</small></span><b>›</b></button><button class="menu-row" data-action="export-parcels-csv"><span>CSV</span><span><strong>Parcelles</strong><small>Liste et attributs</small></span><b>›</b></button><button class="menu-row" data-action="export-geojson"><span>GEO</span><span><strong>GeoJSON</strong><small>Parcelles avec géométries</small></span><b>›</b></button></div>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`,'small');}

async function openDataCenter(){const data=state(),backups=await store.storage.backupList();const deleted=['parcelles','interventions','materiels','documents','photos','points','tasks'].reduce((s,t)=>s+(data[t]||[]).filter(i=>i.deletedAt).length,0);modal('Mes données','Import, sauvegardes et maintenance de l’application.',`<div class="settings-group"><h2>Importer et restaurer</h2><button class="menu-row" data-action="choose-import"><span>⇩</span><span><strong>Importer</strong><small>Excel, CSV, XML, GeoJSON ou SHP</small></span><b>›</b></button><button class="menu-row" data-action="choose-restore"><span>↶</span><span><strong>Restaurer une sauvegarde</strong><small>ZIP complet ou JSON</small></span><b>›</b></button>${backups.length?`<button class="menu-row" data-action="open-auto-backups"><span>⟲</span><span><strong>Sauvegardes automatiques</strong><small>${backups.length} snapshot${backups.length>1?'s':''} local${backups.length>1?'aux':''}</small></span><b>›</b></button>`:''}</div><div class="settings-group"><h2>Sauvegarder</h2><button class="menu-row" data-action="export-complete-backup"><span>⇧</span><span><strong>Sauvegarde complète</strong><small>Données + photos + documents</small></span><b>›</b></button><button class="menu-row" data-action="export-json-backup"><span>{ }</span><span><strong>Sauvegarde JSON</strong><small>Données structurées sans fichiers binaires</small></span><b>›</b></button></div><div class="settings-group"><h2>Maintenance</h2><button class="menu-row" data-action="open-quality"><span>✓</span><span><strong>Qualité des données</strong><small>${dataQuality(data).score}% complets</small></span><b>›</b></button><button class="menu-row" data-action="open-trash"><span>♲</span><span><strong>Corbeille</strong><small>${deleted} élément${deleted!==1?'s':''}</small></span><b>›</b></button><button class="menu-row" data-action="open-log"><span>◷</span><span><strong>Activité</strong><small>${data.journal.length} événements locaux</small></span><b>›</b></button><button class="menu-row" data-action="open-sync"><span>☁</span><span><strong>Synchronisation</strong><small>${escapeHtml(sync.status.message)}</small></span><b>›</b></button><button class="menu-row" data-action="open-diagnostic"><span>ⓘ</span><span><strong>Diagnostic</strong><small>Build, stockage, service worker</small></span><b>›</b></button></div>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`,'large');}
async function openAutoBackups(){const backups=await store.storage.backupList();modal('Sauvegardes automatiques','Snapshots locaux conservés sur cet appareil.',backups.length?`<div class="stack-list">${backups.map(b=>`<div class="list-row"><div><strong>${escapeHtml(localDateTime(b.createdAt))}</strong><small>${escapeHtml(b.id)}</small></div><div><button class="small-button" data-action="restore-auto-backup" data-id="${escapeHtml(b.id)}">Restaurer</button> <button class="small-button danger" data-action="delete-auto-backup" data-id="${escapeHtml(b.id)}">Supprimer</button></div></div>`).join('')}</div>`:'<div class="empty-state">Aucune sauvegarde automatique locale.</div>',`<button class="button secondary" data-action="open-data-center">Retour</button>`,'large');}
async function restoreAutoBackup(id){const backup=await store.storage.backupGet(id);if(!backup?.state)throw new Error('Sauvegarde automatique introuvable.');await exportCompleteBackup();await store.replaceState(backup.state,'Sauvegarde automatique restaurée.',{kind:'restore'});closeModal();toast('Sauvegarde automatique restaurée.');}

function openQuality(){const report=dataQuality(state());modal('Qualité des données','Corrigez les informations manquantes.',`<div class="quality-summary"><strong>${report.score}% complets</strong><div class="quality-progress"><span style="width:${report.score}%"></span></div></div><div class="stack-list">${report.issues.length?report.issues.map(i=>`<div class="list-row"><div><strong>${escapeHtml(i.label)}</strong><small>${escapeHtml(i.code)}</small></div><button class="small-button" data-view="parcels">Voir les parcelles</button></div>`).join(''):'<div class="empty-state">✓ Aucune anomalie détectée.</div>'}</div>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`);}

function openTrash(){const data=state(),types=['parcelles','interventions','materiels','documents','photos','points','tasks','clients'];const rows=types.flatMap(type=>(data[type]||[]).filter(i=>i.deletedAt).map(item=>({type,item})));modal('Corbeille','Restaurez ou supprimez définitivement.',rows.length?`<div class="stack-list">${rows.map(({type,item})=>`<div class="list-row"><div><strong>${escapeHtml(item.nom||item.name||item.type||'Élément')}</strong><small>${escapeHtml(type)} · ${localDate(item.deletedAt)}</small></div><div><button class="small-button" data-action="restore-trash" data-type="${type}" data-id="${item.id}">Restaurer</button> <button class="small-button danger" data-action="purge-trash" data-type="${type}" data-id="${item.id}">Supprimer</button></div></div>`).join('')}</div>`:'<div class="empty-state">La corbeille est vide.</div>',`<button class="button secondary" data-action="close-modal">Fermer</button>`,'large');}
function openLog(){const entries=state().journal;modal('Activité','Les événements importants sont conservés localement.',entries.length?`<ul class="timeline">${entries.slice(0,100).map(i=>`<li><strong>${escapeHtml(i.message)}</strong><small>${localDateTime(i.createdAt)} · ${escapeHtml(i.type)}</small></li>`).join('')}</ul>`:'<div class="empty-state">Aucune activité.</div>',`<button class="button secondary" data-action="close-modal">Fermer</button>`);}
function openSync(){const data=state(),pending=data.queue.filter(i=>i.status==='pending').length,conflicts=active('syncConflicts',data).filter(c=>c.status==='open').length;modal('Synchronisation','La synchronisation reste désactivée sans authentification sécurisée.',`<dl class="definition-list"><div><dt>État</dt><dd>${escapeHtml(sync.status.connected?'Connecté':'Local')}</dd></div><div><dt>En attente</dt><dd>${pending}</dd></div><div><dt>Conflits</dt><dd>${conflicts}</dd></div><div><dt>Dernière sync</dt><dd>${data.metadata.lastSyncAt?localDateTime(data.metadata.lastSyncAt):'Aucune'}</dd></div></dl><div class="notice info" style="margin-top:14px">Aucune donnée n’est envoyée tant que vous n’avez pas activé et configuré un compte.</div>`,`<button class="button secondary" data-action="close-modal">Fermer</button>${sync.status.connected?'<button class="button primary" id="run-sync">Synchroniser</button>':''}`,'small');$('#run-sync')?.addEventListener('click',async()=>{const r=await sync.sync();closeModal();toast(`${r.sent} modification(s) synchronisée(s), ${r.conflicts} conflit(s).`);});}
async function openDiagnostic(){const estimate=await store.storage.estimate(),reg=await navigator.serviceWorker?.getRegistration?.();const data=state();const diag={build:BUILD_ID,schema:APP_VERSION,revision:data.metadata.revision,userAgent:navigator.userAgent,online:navigator.onLine,serviceWorker:Boolean(reg),serviceWorkerController:Boolean(navigator.serviceWorker?.controller),indexedDbFallback:store.storage.usingFallback,storageUsage:estimate.usage,storageQuota:estimate.quota,lastImportAt:data.metadata.lastImportAt,counts:Object.fromEntries(['parcelles','interventions','photos','documents','points','clients'].map(t=>[t,active(t,data).length]))};modal('Diagnostic','Informations utiles pour comprendre un problème.',`<pre style="white-space:pre-wrap;font-size:12px;background:#f3f6f3;padding:12px;border-radius:12px">${escapeHtml(JSON.stringify(diag,null,2))}</pre>`,`<button class="button secondary" id="copy-diagnostic">Copier</button><button class="button secondary" id="clear-cache">Nettoyer le cache</button><button class="button primary" data-action="close-modal">Fermer</button>`,'large');$('#copy-diagnostic').onclick=async()=>{await navigator.clipboard?.writeText(JSON.stringify(diag,null,2));toast('Diagnostic copié.');};$('#clear-cache').onclick=async()=>{await store.storage.clearRuntimeCaches();toast('Cache d’exécution nettoyé. Rechargez l’application.');};}

function openSettings(){const data=state(),farm=data.exploitation,p=data.preferences;modal('Paramètres','Recherchez un réglage ou parcourez les sections.',`<label class="search-field" style="margin-bottom:14px"><span>⌕</span><input id="settings-search" placeholder="Rechercher un réglage…"></label><form id="settings-form"><section class="form-section settings-searchable" data-keywords="exploitation nom commune latitude longitude siège" style="border-top:0;margin-top:0;padding-top:0"><h3>Exploitation</h3><div class="form-grid"><label>Nom<input name="nom" value="${escapeHtml(farm.nom)}"></label><label>Commune<input name="commune" value="${escapeHtml(farm.commune||'')}"></label><label>Latitude<input name="latitude" inputmode="decimal" value="${farm.latitude??''}"></label><label>Longitude<input name="longitude" inputmode="decimal" value="${farm.longitude??''}"></label></div></section><section class="form-section settings-searchable" data-keywords="carte fond satellite culture statut apparence thème sombre contraste itinéraire plans google"><h3>Carte et apparence</h3><div class="form-grid"><label>Fond de carte<select name="mapLayer"><option value="osm" ${p.mapLayer==='osm'?'selected':''}>Standard</option><option value="satellite" ${p.mapLayer==='satellite'?'selected':''}>Satellite</option></select></label><label>Couleur parcelles<select name="mapColorMode"><option value="culture" ${p.mapColorMode==='culture'?'selected':''}>Culture</option><option value="status" ${p.mapColorMode==='status'?'selected':''}>Statut</option></select></label><label>Apparence<select name="theme"><option value="system" ${p.theme==='system'?'selected':''}>Système</option><option value="light" ${p.theme==='light'?'selected':''}>Clair</option><option value="dark" ${p.theme==='dark'?'selected':''}>Sombre</option></select></label><label>Itinéraire<select name="routeProvider"><option value="apple" ${p.routeProvider==='apple'?'selected':''}>Plans Apple</option><option value="google" ${p.routeProvider==='google'?'selected':''}>Google Maps</option></select></label><label><input type="checkbox" name="highContrast" ${p.highContrast?'checked':''}> Contraste renforcé</label></div></section><section class="form-section settings-searchable" data-keywords="météo prévision jours 7 14"><h3>Météo</h3><div class="form-grid"><label>Horizon des prévisions<select name="weatherDays"><option value="7" ${Number(p.weatherDays)!==14?'selected':''}>7 jours</option><option value="14" ${Number(p.weatherDays)===14?'selected':''}>14 jours</option></select></label></div></section><section class="form-section settings-searchable" data-keywords="données confidentialité gps localisation sauvegarde synchronisation cloud"><h3>Données et confidentialité</h3><div class="form-grid"><label><input type="checkbox" name="gpsConsent" ${p.gpsConsent?'checked':''}> Autoriser le GPS après action</label><label><input type="checkbox" name="autoBackup" ${p.autoBackup?'checked':''}> Sauvegarde locale quotidienne</label><label><input type="checkbox" name="syncEnabled" ${p.syncEnabled?'checked':''}> Préparer la synchronisation cloud</label></div><p class="form-note">Le GPS et les données métier ne sont jamais envoyés automatiquement.</p></section></form>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="save-settings">Enregistrer</button>`,'large');
  $('#settings-search').oninput=e=>{const q=normalize(e.target.value);$$('.settings-searchable').forEach(section=>section.classList.toggle('hidden',q&&!normalize(`${section.dataset.keywords} ${section.textContent}`).includes(q)));};$('#save-settings').onclick=async()=>{const f=$('#settings-form'),v=Object.fromEntries(new FormData(f));await store.setExploitation({nom:v.nom.trim()||'Mon exploitation',commune:v.commune.trim(),latitude:toNullableNumber(v.latitude),longitude:toNullableNumber(v.longitude)});await store.setPreferences({mapLayer:v.mapLayer,mapColorMode:v.mapColorMode,theme:v.theme,routeProvider:v.routeProvider,weatherDays:Number(v.weatherDays)===14?14:7,highContrast:f.highContrast.checked,gpsConsent:f.gpsConsent.checked,autoBackup:f.autoBackup.checked,syncEnabled:f.syncEnabled.checked});await sync.init();closeModal();renderAll();toast('Paramètres enregistrés.');};}
function applyTheme(){if(!store)return;const theme=state().preferences.theme||'system';document.documentElement.dataset.theme=theme;document.documentElement.classList.toggle('theme-dark',theme==='dark'||(theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches));document.documentElement.classList.toggle('high-contrast',Boolean(state().preferences.highContrast));}

function openGlobalSearch(){modal('Recherche','Parcelles, travaux, tâches, matériel, clients et points.',`<label class="search-field"><span>⌕</span><input id="global-search-input" data-autofocus placeholder="Rechercher…"></label><div id="global-search-results" style="margin-top:12px"><div class="empty-state">Commencez à saisir.</div></div>`,`<button class="button secondary" data-action="close-modal">Fermer</button>`,'large');$('#global-search-input').oninput=event=>renderGlobalSearch(event.target.value);}
function renderGlobalSearch(query){const root=$('#global-search-results'),q=normalize(query);if(!q){root.innerHTML='<div class="empty-state">Commencez à saisir.</div>';return;}const data=state();const parcelResults=active('parcelles',data).filter(p=>normalize([p.nom,p.culture,p.commune,p.exploitant].join(' ')).includes(q)).slice(0,8),workResults=active('interventions',data).filter(w=>normalize([w.type,w.product,w.note,parcelById(w.parcelId,data)?.nom].join(' ')).includes(q)).slice(0,8),taskResults=active('tasks',data).filter(t=>normalize([t.title,t.note,parcelById(t.parcelId,data)?.nom].join(' ')).includes(q)).slice(0,6),equipmentResults=active('materiels',data).filter(m=>normalize([m.nom,m.note].join(' ')).includes(q)).slice(0,6),clientResults=active('clients',data).filter(c=>normalize([c.name,c.contact,c.note].join(' ')).includes(q)).slice(0,5),pointResults=active('points',data).filter(p=>normalize([p.nom,p.type,p.note,parcelById(p.parcelId,data)?.nom].join(' ')).includes(q)).slice(0,6);
  const section=(title,html)=>html?`<h3>${title}</h3>${html}`:'';root.innerHTML=section('Parcelles',parcelResults.map(p=>`<button class="menu-row" data-action="open-parcel" data-id="${p.id}"><span>◇</span><span><strong>${escapeHtml(p.nom)}</strong><small>${escapeHtml(p.culture||'')} · ${formatNumber(p.surfaceHa)} ha</small></span><b>›</b></button>`).join(''))+section('Travaux',workResults.map(w=>`<button class="menu-row" data-action="edit-work" data-id="${w.id}"><span>✓</span><span><strong>${escapeHtml(w.type)}</strong><small>${escapeHtml(parcelById(w.parcelId,data)?.nom||'')}</small></span><b>›</b></button>`).join(''))+section('Tâches',taskResults.map(t=>`<button class="menu-row" data-action="edit-task" data-id="${t.id}"><span>☑</span><span><strong>${escapeHtml(t.title)}</strong><small>${escapeHtml(parcelById(t.parcelId,data)?.nom||t.status||'')}</small></span><b>›</b></button>`).join(''))+section('Matériel',equipmentResults.map(m=>`<button class="menu-row" data-action="edit-equipment" data-id="${m.id}"><span>⚙</span><span><strong>${escapeHtml(m.nom)}</strong><small>${formatNumber(m.currentMeter)} h</small></span><b>›</b></button>`).join(''))+section('Clients',clientResults.map(c=>`<button class="menu-row" data-action="edit-client" data-id="${c.id}"><span>⌘</span><span><strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(c.contact||'')}</small></span><b>›</b></button>`).join(''))+section('Points',pointResults.map(p=>`<button class="menu-row" data-action="show-point" data-id="${p.id}"><span>⌖</span><span><strong>${escapeHtml(p.nom||p.type)}</strong><small>${escapeHtml(parcelById(p.parcelId,data)?.nom||p.type||'')}</small></span><b>›</b></button>`).join(''));if(!root.textContent.trim())root.innerHTML='<div class="empty-state">Aucun résultat.</div>';}

function routeParcel(id){const p=parcelById(id),center=p?routePointForParcel(p):null;if(!p||!center||!Number.isFinite(Number(center.latitude))){toast('Cette parcelle n’a pas de géométrie exploitable.','error');return;}const provider=state().preferences.routeProvider||'apple',url=provider==='google'?`https://www.google.com/maps/dir/?api=1&destination=${center.latitude},${center.longitude}`:`https://maps.apple.com/?daddr=${center.latitude},${center.longitude}`;window.open(url,'_blank','noopener');}
async function shareParcel(id){const p=parcelById(id),center=geometryCentroid(p?.geometry),text=`${p.nom} — ${formatNumber(p.surfaceHa)} ha — ${p.culture||'culture non renseignée'}${p.commune?` — ${p.commune}`:''}${center?` — ${center.latitude.toFixed(6)}, ${center.longitude.toFixed(6)}`:''}`;if(navigator.share){try{await navigator.share({title:p.nom,text});return;}catch{}}await navigator.clipboard?.writeText(text);toast('Résumé de la parcelle copié.');}

async function handleImportFiles(event){pendingImportFiles=[...event.target.files];event.target.value='';if(!pendingImportFiles.length)return;await inspectAndShowImport(pendingImportFiles,{});}
async function inspectAndShowImport(files,mapping){
  try{modal('Analyse de l’import','Aucune donnée n’est modifiée pendant cette étape.','<div class="empty-state">Analyse des fichiers…</div>','','small');const preview=await inspectFiles(files,state(),mapping);if(!preview.sources.length){modal('Import impossible','Aucune source valide.',preview.invalid.map(i=>`<div class="notice danger">${escapeHtml(i.file)} : ${escapeHtml(i.message)}</div>`).join(''),'<button class="button primary" data-action="close-modal">Fermer</button>','small');return;}if(previewNeedsMapping(preview)){openMapping(preview,files);return;}showImportPreview(preview);}catch(error){closeModal();toast(`Analyse impossible : ${error.message}`,'error');}
}
function openMapping(preview,files){const options=mappingOptions(preview),select=(name,label)=>`<label>${label}<select name="${name}"><option value="">Non associé</option>${options.map(o=>`<option value="${escapeHtml(o)}">${escapeHtml(o)}</option>`).join('')}</select></label>`;modal('Correspondance des colonnes','Aucune parcelle n’a été reconnue automatiquement. Associez au minimum le nom.',`<form id="mapping-form" class="form-grid">${select('name','Nom de parcelle *')}${select('sourceId','Identifiant source')}${select('surfaceHa','Surface')}${select('culture','Culture')}${select('commune','Commune')}${select('ilot','Îlot')}</form>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="apply-mapping">Ré-analyser</button>`);$('#apply-mapping').onclick=async()=>{const mapping=Object.fromEntries(new FormData($('#mapping-form')));if(!mapping.name){toast('Associez la colonne du nom de parcelle.','error');return;}await inspectAndShowImport(files,mapping);};}
function showImportPreview(preview){modal('Vérifier l’import','Contrôlez les données avant validation.',`${importPreviewHtml(preview)}<label class="field-label" style="margin-top:14px">Pour les correspondances existantes<select id="import-strategy"><option value="merge">Fusionner sans effacer mes valeurs</option><option value="replace">Utiliser les valeurs importées</option><option value="ignore">Ignorer</option><option value="new">Créer de nouvelles parcelles</option></select></label>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="apply-import">Importer</button>`,'large');$('#apply-import').onclick=async()=>{const b=$('#apply-import');b.disabled=true;b.textContent='Import en cours…';try{const result=await applyImport(preview,store,$('#import-strategy').value);closeModal();toast(`Import terminé : ${result.created} créée(s), ${result.updated} mise(s) à jour, ${result.interventions} travail(aux).`);switchView('map');parcelMap.fitParcels();}catch(error){b.disabled=false;b.textContent='Importer';toast(error.message,'error');}};}

async function exportCompleteBackup(){try{const {blob,manifest}=await createCompleteBackup(store);downloadBlob(`parcelles-sauvegarde-complete-${isoDate(manifest.createdAt)}.zip`,blob);toast('Sauvegarde complète téléchargée.');}catch(error){toast(`Sauvegarde impossible : ${error.message}`,'error');}}
async function exportJsonBackup(){const backup=await makeBackup(state());download(`parcelles-donnees-${isoDate(backup.createdAt)}.json`,JSON.stringify(backup,null,2));toast('Sauvegarde JSON téléchargée.');}
async function handleRestoreFile(event){const file=event.target.files[0];event.target.value='';if(!file)return;try{let parsed;if(file.name.toLowerCase().endsWith('.zip'))parsed=await parseCompleteBackup(file);else parsed=await validateBackup(JSON.parse(await file.text()));const counts=parsed.meta.counts||{};modal('Restaurer la sauvegarde','L’état actuel sera d’abord sauvegardé.',`<div class="preview-summary"><div class="preview-stat"><strong>${counts.parcelles||0}</strong><small>parcelles</small></div><div class="preview-stat"><strong>${counts.interventions||0}</strong><small>travaux</small></div><div class="preview-stat"><strong>${counts.photos||0}</strong><small>photos</small></div></div><div class="notice info">${parsed.meta.complete?'Sauvegarde complète avec pièces jointes.':'Sauvegarde JSON sans blobs.'}</div>`,`<button class="button secondary" data-action="close-modal">Annuler</button><button class="button primary" id="confirm-restore">Sauvegarder puis restaurer</button>`,'small');$('#confirm-restore').onclick=async()=>{await exportCompleteBackup();if(parsed.meta.complete)await restoreCompleteBackup(parsed,store);else await store.replaceState(parsed.data,'Sauvegarde JSON restaurée.',{kind:'restore'});closeModal();toast('Sauvegarde restaurée.');};}catch(error){toast(`Restauration refusée : ${error.message}`,'error');}}

function openWorkFilters(){const data=state(),parcels=active('parcelles',data),types=[...new Set(active('interventions',data).map(w=>w.type).filter(Boolean))].sort();modal('Filtres des travaux','Affinez la liste sans perdre votre recherche.',`<form id="work-filter-form" class="form-grid"><label>Parcelle<select name="parcel"><option value="">Toutes</option>${parcels.map(p=>`<option value="${p.id}" ${workFilters.parcel===p.id?'selected':''}>${escapeHtml(p.nom)}</option>`).join('')}</select></label><label>Type<select name="type"><option value="">Tous</option>${types.map(t=>`<option ${workFilters.type===t?'selected':''}>${escapeHtml(t)}</option>`).join('')}</select></label></form>`,`<button class="button secondary" id="reset-work-filters">Effacer</button><button class="button primary" id="apply-work-filters">Appliquer</button>`,'small');$('#apply-work-filters').onclick=()=>{workFilters=Object.fromEntries(new FormData($('#work-filter-form')));closeModal();renderWork(state());};$('#reset-work-filters').onclick=()=>{workFilters={parcel:'',type:''};closeModal();renderWork(state());};}

function openHelp(){modal('Aide','Les actions courantes sont accessibles en un ou deux niveaux.',`<h3>Commencer</h3><p>Importez vos parcelles depuis <strong>Plus → Mes données → Importer</strong>, ou créez une parcelle manuellement.</p><h3>Sur le terrain</h3><p>Le mode terrain utilise le GPS uniquement après votre action, trie les parcelles par distance et détecte la parcelle dans laquelle vous vous trouvez lorsque la géométrie est disponible.</p><h3>Hors connexion</h3><p>Les données métier sont enregistrées sur l’appareil. Les services réseau comme la météo, le RPG et la synchronisation peuvent être indisponibles sans bloquer la saisie.</p><h3>Sauvegardes</h3><p>La sauvegarde complète ZIP contient l’état structuré, les photos et les documents.</p>`,`<button class="button primary" data-action="close-modal">Compris</button>`);}

function bindEvents(){
  document.addEventListener('click',async event=>{
    const control=event.target.closest('[data-action],[data-view],[data-work-tab],[data-parcel-filter],[data-map-open]');if(!control)return;
    if(control.dataset.view){closeModal();switchView(control.dataset.view);return;}
    if(control.dataset.workTab){workTab=control.dataset.workTab;$$('[data-work-tab]').forEach(b=>b.classList.toggle('is-active',b===control));renderWork(state());return;}
    if(control.dataset.parcelFilter){parcelFilter=control.dataset.parcelFilter;$$('[data-parcel-filter]').forEach(b=>b.classList.toggle('is-active',b===control));renderParcels(state());return;}
    if(control.dataset.mapOpen){closeModal();selectedParcelId=control.dataset.mapOpen;renderMapSheet();return;}
    const action=control.dataset.action,id=control.dataset.id;
    try{
      if(action==='close-modal')closeModal();
      else if(action==='global-search')openGlobalSearch();
      else if(action==='network-details')modal('État de l’application',navigator.onLine?'Connexion disponible':'Hors connexion',`<div class="notice ${navigator.onLine?'info':'warning'}">${navigator.onLine?'Les fonctions réseau sont disponibles.':'Les données locales restent accessibles et modifiables.'}</div>`,`<button class="button primary" data-action="close-modal">Fermer</button>`,'small');
      else if(action==='new-parcel')openParcelForm();
      else if(action==='open-parcel'){closeModal();closeFieldMode();openParcel(id);}
      else if(action==='edit-parcel'){closeModal();openParcelForm(parcelById(id));}
      else if(action==='delete-parcel')confirmDelete('parcelles',id,'cette parcelle');
      else if(action==='parcel-actions'){closeModal();openParcelActions(id);}
      else if(action==='parcel-tab'){openParcelDetail(id,control.dataset.tab);}
      else if(action==='toggle-favorite'){const p=parcelById(id);await store.upsert('parcelles',{...p,favorite:!p.favorite},{label:`Favori ${!p.favorite?'activé':'désactivé'} : ${p.nom}`,queue:false});openParcelDetail(id);}
      else if(action==='add-note'){closeModal();openNote(id);}
      else if(action==='new-work'){closeModal();closeFieldMode();openWorkForm(null,control.dataset.parcelId||id||null);}
      else if(action==='batch-work'){closeModal();openBatchWorkForm();}
      else if(action==='edit-work'){closeModal();openWorkForm(store.get('interventions',id));}
      else if(action==='duplicate-work'){closeModal();openWorkForm(store.get('interventions',id),null,{duplicate:true});}
      else if(action==='finish-work'){const w=store.get('interventions',id);await store.upsert('interventions',{...w,status:'Terminé',date:todayIso()},{label:`Travail terminé : ${w.type}`});toast('Travail marqué terminé.','success',{label:'Annuler',run:()=>store.upsert('interventions',w,{label:'Statut restauré'})});}
      else if(action==='add-photo'){closeModal();openAttachmentForm(id,{photoOnly:true});}
      else if(action==='attach-file'){closeModal();openAttachmentForm(id);}
      else if(action==='view-attachment'){await viewAttachment(control.dataset.type,id);}
      else if(action==='show-point'){const point=store.get('points',id);if(point){closeModal();switchView('map');parcelMap.map?.setView([Number(point.latitude),Number(point.longitude)],18);}}
      else if(action==='route-parcel')routeParcel(id);
      else if(action==='draw-parcel'){closeModal();startParcelDrawing(id);}
      else if(action==='share-parcel')await shareParcel(id);
      else if(action==='locate')await requestGps();
      else if(action==='fit-parcels')parcelMap.fitParcels();
      else if(action==='open-map-layers')openMapLayers();
      else if(action==='add-point')openPointCreator();
      else if(action==='toggle-legend')$('#map-legend')?.classList.toggle('is-open');
      else if(action==='finish-parcel-draw'){try{parcelMap.finishPolygonDrawing();}catch(error){toast(error.message,'error');}}
      else if(action==='cancel-parcel-draw'){parcelMap.cancelPolygonDrawing();$('#map-draw-panel').classList.add('hidden');drawingParcelId=null;}
      else if(action==='undo-draw-point'){parcelMap.undoPolygonPoint();}
      else if(action==='open-field-mode')openFieldMode();
      else if(action==='open-day-route')openDayRoute();
      else if(action==='open-rotations')openRotations();
      else if(action==='add-rotation'){closeModal();openRotationForm(id);}
      else if(action==='edit-rotation'){const r=store.get('rotations',id);if(r){closeModal();openRotationForm(r.parcelId,r);}}
      else if(action==='open-equipment')openEquipment();
      else if(action==='new-equipment'){closeModal();openEquipmentForm();}
      else if(action==='edit-equipment'){closeModal();openEquipmentForm(store.get('materiels',id));}
      else if(action==='open-grazing')openGrazing();
      else if(action==='new-grazing'){closeModal();openGrazingForm();}
      else if(action==='edit-grazing'){const g=store.get('grazingSessions',id);if(g){closeModal();openGrazingForm(g);}}
      else if(action==='end-grazing'){const s=store.get('grazingSessions',id);await store.upsert('grazingSessions',{...s,endDate:todayIso()},{label:'Sortie de pâturage enregistrée.'});openGrazing();}
      else if(action==='open-clients')openClients();
      else if(action==='new-client'){closeModal();openClientForm();}
      else if(action==='edit-client'){closeModal();openClientForm(store.get('clients',id));}
      else if(action==='open-tasks')openTasks();
      else if(action==='new-task'){closeModal();openTaskForm();}
      else if(action==='edit-task'){closeModal();openTaskForm(store.get('tasks',id));}
      else if(action==='finish-task'){const t=store.get('tasks',id);await store.upsert('tasks',{...t,status:'Terminé'},{label:`Tâche terminée : ${t.title}`});if($('#modal-root').classList.contains('has-modal'))openTasks();else renderToday(state());toast('Tâche terminée.');}
      else if(action==='open-calendar')openCalendar();
      else if(action==='calendar-day')renderCalendarDay(control.dataset.date);
      else if(action==='open-weather')openWeather();
      else if(action==='refresh-weather'){closeModal();await refreshWeather();}
      else if(action==='open-assistant')openAssistant();
      else if(action==='open-reports')openReports();
      else if(action==='open-data-center')await openDataCenter();
      else if(action==='open-quality')openQuality();
      else if(action==='open-trash')openTrash();
      else if(action==='restore-trash'){await store.restore(control.dataset.type,id);openTrash();}
      else if(action==='purge-trash'){await store.purge(control.dataset.type,id);openTrash();toast('Élément supprimé définitivement.');}
      else if(action==='open-auto-backups')await openAutoBackups();
      else if(action==='restore-auto-backup')await restoreAutoBackup(id);
      else if(action==='delete-auto-backup'){await store.storage.backupDelete(id);await openAutoBackups();}
      else if(action==='clear-work-filter'){workFilters={...workFilters,[control.dataset.filter]:''};renderWork(state());}
      else if(action==='clear-work-filters'){workFilters={parcel:'',type:''};renderWork(state());}
      else if(action==='open-log')openLog();
      else if(action==='open-sync')openSync();
      else if(action==='open-diagnostic')await openDiagnostic();
      else if(action==='open-settings')openSettings();
      else if(action==='open-help')openHelp();
      else if(action==='choose-import'){$('#import-file-input').click();}
      else if(action==='choose-restore'){$('#restore-file-input').click();}
      else if(action==='export-complete-backup')await exportCompleteBackup();
      else if(action==='export-json-backup')await exportJsonBackup();
      else if(action==='export-work-csv'){download(`parcelles-travaux-${todayIso()}.csv`,exportCsv(state()),'text/csv;charset=utf-8');toast('CSV des travaux téléchargé.');}
      else if(action==='export-parcels-csv'){download(`parcelles-liste-${todayIso()}.csv`,exportParcelsCsv(state()),'text/csv;charset=utf-8');toast('CSV des parcelles téléchargé.');}
      else if(action==='export-geojson'){download(`parcelles-${todayIso()}.geojson`,exportGeoJson(state()),'application/geo+json;charset=utf-8');toast('GeoJSON téléchargé.');}
      else if(action==='work-filters')openWorkFilters();
    }catch(error){console.error(error);toast(error.message||'Une erreur est survenue.','error');}
  });

  document.addEventListener('input',event=>{
    if(event.target.matches('#parcel-search'))renderParcels(state());
    if(event.target.matches('#work-search'))renderWork(state());
    if(event.target.matches('#map-search-input'))renderMapSearch(event.target.value);
  });
  document.addEventListener('change',event=>{if(event.target.matches('#parcel-sort'))renderParcels(state());});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'){parcelMap.cancelPointPlacement();if(drawingParcelId){parcelMap.cancelPolygonDrawing();$('#map-draw-panel').classList.add('hidden');drawingParcelId=null;}if($('#modal-root').classList.contains('has-modal'))closeModal();}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openGlobalSearch();}if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||'')){event.preventDefault();openGlobalSearch();}});
  $('#import-file-input').addEventListener('change',handleImportFiles);$('#restore-file-input').addEventListener('change',handleRestoreFile);
}

function renderMapSearch(value){const root=$('#map-search-results'),q=normalize(value);if(!q){root.classList.add('hidden');root.innerHTML='';return;}const rows=active('parcelles').filter(p=>normalize([p.nom,p.culture,p.commune].join(' ')).includes(q)).slice(0,8);root.innerHTML=rows.map(p=>`<button class="map-search-result" data-action="map-search-open" data-id="${p.id}"><strong>${escapeHtml(p.nom)}</strong><small>${escapeHtml(p.culture||'')} · ${formatNumber(p.surfaceHa)} ha</small></button>`).join('')||'<div class="empty-state">Aucun résultat.</div>';root.classList.remove('hidden');root.querySelectorAll('[data-action="map-search-open"]').forEach(button=>button.onclick=()=>{selectedParcelId=button.dataset.id;parcelMap.select(button.dataset.id);root.classList.add('hidden');$('#map-search-input').value='';});}

init().catch(error=>{console.error(error);document.body.innerHTML=`<main style="padding:2rem;font-family:system-ui"><h1>Impossible de démarrer Parcelles</h1><p>${escapeHtml(error.message)}</p><p>Build ${BUILD_ID}</p></main>`;});
